		&XMLWhenReportLoading;
		&XMLWhenReportClosing;






			&DeclareCommandFilter;



				&QueryString;


declare @queryWhereClause nvarchar(4000), @queryFormClause nvarchar(4000)
select @queryWhereClause = 'b.status <> ''*'''
IF @ma_kh <> '' SET @queryWhereClause += ' and b.ma_kh like ''' + REPLACE(RTRIM(@ma_kh), '''', '''''') + '%'''

&FilterInitialize;&FilterQuery;


select top 0 a.*, b.ma_lsx
		, cast('' as varchar(33)) stt_rec_sf2, cast('' as varchar(33)) ma_sp, cast('' as varchar(33)) so_lsx, cast('' as varchar(33)) stt_rec_lsx
		, cast('' as varchar(33)) stt_rec_dh, cast('' as varchar(33)) dh_ma_kh
	into #ds1 
	from ds1$000000 a, ms1$000000 b 

set @q = '
insert into #ds1 
	select a.*, b.ma_lsx, '''', '''', '''', '''', '''', '''' 
		from ds1$%Partition a 
			join ms1$%Partition b on a.stt_rec = b.stt_rec 
		where %[b.status not in (''0'', ''*'')]%'
exec FastBusiness$Partition$Execute @q, NULL, 'a.ngay_ct', @tu_ngay, @den_ngay, @@userID, @@admin

update #ds1 set stt_rec_sf2 = b.stt_rec from #ds1 a join cs2$000000 b on a.ma_lsx = b.ma_lsx and b.status <> '*'

set @q = ''
select @q = @q + char(13) +  '
update #ds1 set ma_sp = b.ma_sp, so_lsx = b.so_lsx, stt_rec_lsx = b.stt_rec_lsx 
	from #ds1 a 
		join ms2$'+convert(char(6), b.ngay_ct, 112)+' b on a.stt_rec_sf2 = b.stt_rec
'
from #ds1 a 
	join cs2$000000 b on a.stt_rec_sf2 = b.stt_rec
group by convert(char(6), b.ngay_ct, 112)
exec sp_executesql @q

update a set stt_rec_dh = b.stt_rec_dh
	from #ds1 a
		join ctsx b on a.stt_rec_lsx = b.stt_rec and a.ma_sp = b.ma_vt

set @q = ''
select @q = @q + '
update #ds1 set dh_ma_kh = b.ma_kh
	from #ds1 a
		join m64$'+convert(char(6), b.ngay_ct, 112)+' b on a.stt_rec_dh = b.stt_rec
'
from #ds1 a 
	join c64$000000 b on a.stt_rec_dh = b.stt_rec
group by convert(char(6), b.ngay_ct, 112)
exec sp_executesql @q

if @ma_kh <> '' delete #ds1 where dh_ma_kh <> @ma_kh

select @q =  '
select ' + @@textExternal + ' 
	from #ds1 a 
		left join dmvt b on a.ma_vt = b.ma_vt
	'+ case when @$primeFilter = '' then '' else ' where ' end + @$primeFilter + '
	order by a.ngay_ct, a.stt_rec, a.line_nbr'
exec(@q)







